  _ = `Кнопка воспроизведения трейлера`,
  _ = `Цвет кнопки воспроизведения`,
  _ = `Цвет кнопки воспроизведения, отображаемой поверх каждого трейлера в этом разделе. Не меняйте его, если хотите использовать цвет по умолчанию.`,
  _ = `Цвет кнопки воспроизведения при наведении`,
  _ = `Цвет кнопки воспроизведения, когда пользователь наводит на неё курсор. Этот параметр влияет на все трейлеры в этом разделе. Не меняйте его, если хотите использовать цвет по умолчанию.`,
  _ = `Стандартное отображение трейлера`,
  _ = `Задаёт то, как медиафайл выглядит до нажатия: как скриншот трейлера, как микротрейлер на повторе или как скриншот, при наведении на который запускается повтор микротрейлера. Нажатие на любой из этих элементов воспроизведёт трейлер в диалоговом окне.`,
  _ = `Соотношение сторон`,
  _ = `16:9`,
  _ = `Соотношение ширины и высоты, необходимое для того, чтобы на странице было выделено место для иллюстрации, пока она скачивается. Соотношение записывается при загрузке иллюстрации на сервер; введите его вручную для иллюстраций, загруженных ранее.`,
  _ = `Найти соотношение`,
