  _ = `Альтернативный текст`,
  _ = `Текст для программ чтения с экрана и ситуаций, когда изображение не загружается.`,
  _ = `Необязательная ссылка`,
  _ = `При желании введите ссылку`,
  _ = `При желании вы можете предоставить ссылку, и пользователи смогут переходить на указанный сайт, нажав на медиаконтент.`,
  _ = `Изменить порядок строк`,
