  _ = `Все черновики были опубликованы`,
  _ = `Последнее обновление`,
  _ = `Последняя публикация`,
  _ = `Управление статьями`,
  _ = `Статьи не найдены.`,
  _ = `Создать новую статью...`,
  _ = `Предоставьте название новой статьи. Оно появится только в меню для внутреннего использования.`,
  _ = `Введите название для внутреннего использования`,
  _ = `Обновить перевод...`,
  _ = `Обновить перевод`,
  _ = `Нажмите ниже, чтобы импортировать и опубликовать все одобренные переводы статей из Crowdin (%1$s).`,
  _ = `ПРЕДУПРЕЖДЕНИЕ: Crowdin работает медленно, это может занять более часа.`,
  _ = `Обработка: %1$s`,
  _ = `Опубликовать частые вопросы для следующих языков:`,
  _ = `без изменений`,
